    const sabCount=setup.count<=6?1:setup.count<=10?2:3,indices=shuffle(roster.map((_,i)=>i)),sabIdx=new Set(indices.slice(0,sabCount));let fixerIdx=-1;if(setup.fixer){fixerIdx=indices.find(i=>!sabIdx.has(i))??-1}
