  function buildTaskStations(map,n){const zones=map.zones||[],out=[];for(let i=0;i<Math.min(n,zones.length);i++){const z=zones[i],spec=TASK_NAMES[i%TASK_NAMES.length];out.push({id:`task${i}`,name:spec[0],kind:spec[1],zone:z.name,x:z.x+z.w*(.25+.5*((i*37)%100)/100),z:z.z+z.d*(.25+.5*((i*61)%100)/100)})}if(out.length<6){for(let i=out.length;i<6;i++){const z=zones[i%zones.length]||{name:'MAIN AREA',x:map.w/2-100,z:map.d/2-100,w:200,d:200},spec=TASK_NAMES[i];out.push({id:`task${i}`,name:spec[0],kind:spec[1],zone:z.name,x:z.x+z.w*.5,z:z.z+z.d*.5})}}return out}
