  function tryMove(a,dx,dz){const nx=clamp(a.x+dx,18,state.map.w-18),nz=clamp(a.z+dz,18,state.map.d-18),r=18;if(!blocked(nx,a.z,r))a.x=nx;if(!blocked(a.x,nz,r))a.z=nz}
