  function updateBots(dt){for(const a of state.actors){if(!a.bot||state.phase!=='playing')continue;if(!a.alive){if(a.ghost&&a.role!=='saboteur')botGhostTask(a);continue;}a.aiTimer-=dt;if(a.aiTimer>0)continue;a.aiTimer=a.difficulty==='easy'?rand(.8,1.7):a.difficulty==='hard'?rand(.25,.65):rand(.45,1);const zone=zoneAt(a.x,a.z);a.lastZone=zone?.name||'open area';if(a.role==='saboteur')botSaboteur(a,dt);else botCrew(a,dt)}}
