  function botSaboteur(a){const livingCrew=state.actors.filter(x=>x.alive&&x.role!=='saboteur');if(!livingCrew.length)return;const target=livingCrew.sort((x,y)=>dist(a,x)-dist(a,y))[0],nearWitness=state.actors.some(x=>x.alive&&x.id!==a.id&&x.id!==target.id&&dist(a,x)<150);if(target&&dist(a,target)<70&&a.killCooldown<=0&&!nearWitness){eliminate(a,target);return}if(state.sabotageCooldown<=0&&!state.sabotage&&Math.random()<(a.difficulty==='hard'?.35:.15)){triggerSabotage(pick(Object.keys(SABOTAGES)),a);return}if(target&&dist(a,target)<440)moveToward(a,target.x,target.z);else{const fake=pick(state.taskStations);moveToward(a,fake.x,fake.z)}}
