  function nearestTask(a,range=82){const tasks=a.role==='saboteur'?state.taskStations:a.tasks.filter(t=>!t.done);let best=null,bd=range;for(const t of tasks){const d=dist(a,t);if(d<bd){bd=d;best=t}}return best}
