  function primaryAction(){if(!state||state.phase!=='playing')return;const p=state.player;if(!p.alive&&!(p.ghost&&p.role!=='saboteur'))return;if(p.role==='saboteur'){const target=nearestKillTarget(p);if(target&&p.killCooldown<=0){eliminate(p,target);return}const t=nearestTask(p);if(t){showFakeTask(t);return}}else{const t=nearestTask(p);if(t){openTask(t);return}if(state.sabotage?.critical&&dist(p,state.taskStations[0])<90){clearSabotage(`${p.person.name} repaired the generator.`);return}}}
