  function openTask(task){if(state.player.role==='saboteur')return showFakeTask(task);state.running=false;const wrap=document.createElement('div');wrap.className='fs-task-modal';wrap.id='fsTaskModal';wrap.innerHTML=`<div class="fs-task-box"><span class="eyebrow">${task.zone}</span><h2>${task.name}</h2><p>${task.kind==='hold'?'Hold the control until the repair completes.':'Tap the family chore buttons in order.'}</p>${task.kind==='hold'?`<button id="fsTaskHold" class="fs-task-hold">HOLD TO FIX</button>`:`<div class="fs-task-sequence">${[1,2,3,4].map(n=>`<button data-step="${n}">${n}</button>`).join('')}</div>`}<button id="fsTaskCancel" class="btn secondary">CANCEL</button></div>`;document.body.appendChild(wrap);const finish=()=>{task.done=true;state.player.completed++;state.teamTaskDone++;wrap.remove();state.running=true;last=performance.now();raf=requestAnimationFrame(loop);toast(`${task.name} complete.`);checkWins()};wrap.querySelector('#fsTaskCancel').onclick=()=>{wrap.remove();state.running=true;last=performance.now();raf=requestAnimationFrame(loop)};if(task.kind==='sequence'){let next=1;wrap.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{if(+b.dataset.step!==next){toast('Wrong order. Start again.');next=1;wrap.querySelectorAll('[data-step]').forEach(x=>x.classList.remove('done'));return}b.classList.add('done');next++;if(next===5)setTimeout(finish,180)})}else{const b=wrap.querySelector('#fsTaskHold');let timer=null,progress=0;const start=()=>{timer=setInterval(()=>{progress+=.08;b.style.background=`conic-gradient(#6f9e73 ${progress*100}%,#362719 0)`;b.textContent=`${Math.min(100,Math.round(progress*100))}%`;if(progress>=1){clearInterval(timer);finish()}},80)};const stop=()=>{clearInterval(timer);timer=null};b.onpointerdown=start;b.onpointerup=stop;b.onpointercancel=stop;b.onpointerleave=stop}}
