  function openVentMenu(){const p=state.player;if(p.ventCooldown>0)return toast(`Vent cooldown ${Math.ceil(p.ventCooldown)}s`);const v=nearestVent(p,95);if(!v)return toast('Move next to a service vent.');ventModal(v)}
  function ventModal(v){const allowed=state.player.role==='saboteur'||state.player.role==='fixer';if(!allowed)return;state.running=false;const dests=v.links.map(id=>state.vents.find(x=>x.id===id)).filter(Boolean);const wrap=document.createElement('div');wrap.className='fs-task-modal';wrap.id='fsTaskModal';wrap.innerHTML=`<div class="fs-task-box"><span class="eyebrow">SERVICE VENT</span><h2>${v.zone}</h2><p>Choose a connected room. Only your role knows this route is available.</p><div class="fs-task-sequence" style="flex-wrap:wrap">${dests.map(d=>`<button style="width:140px;height:72px;font-size:11px" data-vent="${d.id}">${d.zone}</button>`).join('')}</div><button id="fsTaskCancel" class="btn secondary">STAY HERE</button></div>`;document.body.appendChild(wrap);wrap.querySelector('#fsTaskCancel').onclick=()=>{wrap.remove();state.running=true;last=performance.now();raf=requestAnimationFrame(loop)};wrap.querySelectorAll('[data-vent]').forEach(b=>b.onclick=()=>{const d=state.vents.find(x=>x.id===b.dataset.vent);state.player.x=d.x;state.player.z=d.z;state.player.ventCooldown=state.player.role==='fixer'?20:4;wrap.remove();state.running=true;last=performance.now();raf=requestAnimationFrame(loop);toast(`Moved through the service vents to ${d.zone}.`)})}
  function openSabotageMenu(){if(state.sabotage)return toast('A sabotage is already active.');if(state.sabotageCooldown>0)return toast(`Sabotage cooldown ${Math.ceil(state.sabotageCooldown)}s`);state.running=false;const wrap=document.createElement('div');wrap.className='fs-task-modal';wrap.id='fsTaskModal';wrap.innerHTML=`<div class="fs-task-box"><span class="eyebrow">SABOTEUR CONTROL</span><h2>Choose a sabotage</h2><div class="fs-task-sequence" style="flex-wrap:wrap">${Object.values(SABOTAGES).map(s=>`<button style="width:145px;height:86px;font-size:11px" data-sab="${s.id}">${s.name}<small style="display:block;font-size:9px;margin-top:4px">${s.critical?'CRITICAL':'DISRUPTION'}</small></button>`).join('')}</div><button id="fsTaskCancel" class="btn secondary">CANCEL</button></div>`;document.body.appendChild(wrap);wrap.querySelector('#fsTaskCancel').onclick=()=>{wrap.remove();state.running=true;last=performance.now();raf=requestAnimationFrame(loop)};wrap.querySelectorAll('[data-sab]').forEach(b=>b.onclick=()=>{triggerSabotage(b.dataset.sab,state.player);wrap.remove();state.running=true;last=performance.now();raf=requestAnimationFrame(loop)})}
  function triggerSabotage(id,actor){const spec=SABOTAGES[id];if(!spec||state.sabotage)return;state.sabotage={...spec,left:spec.duration,by:actor?.id};state.sabotageCooldown=32;state.visionPenalty=id==='lights'?.63:0;state.radioJammed=id==='radio';addChat(actor||state.player,`${spec.name} triggered.`,true)}
