  function clearSabotage(msg='Sabotage cleared.'){state.sabotage=null;state.visionPenalty=0;state.radioJammed=false;toast(msg)}
  function toggleTaskMap(){toast(state.radioJammed?'The radio is jammed. Your task map is unavailable.':`Chores: ${state.player.tasks.filter(t=>!t.done).map(t=>t.zone).join(' · ')||'All chores complete!'}`)}

