  function botMeetingStatements(){for(const a of state.actors){if(!a.bot||!a.alive)continue;const zone=a.lastZone||zoneAt(a.x,a.z)?.name||'somewhere';let text=`I was in ${zone}.`;if(a.witnessed.size){const id=[...a.witnessed][0],p=state.actors.find(x=>x.id===id);if(p)text=`I saw ${p.person.name} very close to where things got weird.`}else if(a.role==='saboteur'&&Math.random()<.55){const innocent=pick(state.actors.filter(x=>x.alive&&x.role!=='saboteur'&&x.id!==a.id));if(innocent)text=`I think ${innocent.person.name} was acting suspicious.`}state.meeting.messages.push({name:a.person.name,text,system:false})}}
  function renderMeeting(){document.querySelector('#fsMeeting')?.remove();const alive=state.actors.filter(a=>a.alive),m=state.meeting,back=document.createElement('div');back.id='fsMeeting';back.className='fs-meeting-back';back.innerHTML=`<div class="fs-meeting"><div class="fs-meeting-title"><span>${m.kind==='report'?'BODY REPORTED':'EMERGENCY MEETING'} · SECRET ROLES STAY SECRET</span><h2>Talk it out. Then vote.</h2><p class="subtext">You can vote for one living player or skip. Ties eject nobody.</p></div><div class="fs-meeting-grid"><div><div class="fs-voters">${state.actors.map(a=>`<button class="fs-voter ${a.alive?'':'dead'}" data-vote="${a.id}" ${a.alive?'':'disabled'}><img src="${spritePath(a.person,a.style)}" alt="${a.person.name}"><strong>${a.person.name}</strong><small>${a.alive?'ALIVE':'OUT'}</small></button>`).join('')}</div><div class="fs-vote-bar"><button id="fsSkipVote" class="btn secondary">SKIP VOTE</button><button id="fsCastVote" class="btn danger" disabled>CAST VOTE</button></div></div><div class="fs-meeting-chat"><div class="fs-drawer-head"><b>Meeting Chat</b><span class="pill subtle">${alive.length} alive</span></div><div id="fsMeetingChat" class="fs-chat-log">${m.messages.map(msgHTML).join('')}</div><div class="fs-chat-row"><input id="fsMeetingInput" maxlength="100" placeholder="Your alibi..."><button id="fsMeetingSend">SEND</button></div></div></div></div>`;document.body.appendChild(back);back.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{m.selected=b.dataset.vote;back.querySelectorAll('[data-vote]').forEach(x=>x.classList.toggle('selected',x===b));back.querySelector('#fsCastVote').disabled=false});back.querySelector('#fsSkipVote').onclick=()=>{m.selected='skip';back.querySelectorAll('[data-vote]').forEach(x=>x.classList.remove('selected'));back.querySelector('#fsCastVote').disabled=false};back.querySelector('#fsCastVote').onclick=resolveMeeting;back.querySelector('#fsMeetingSend').onclick=meetingSend;back.querySelector('#fsMeetingInput').onkeydown=e=>{if(e.key==='Enter')meetingSend()}}
  function meetingSend(){const input=document.querySelector('#fsMeetingInput'),text=input?.value.trim();if(!text)return;state.meeting.messages.push({name:state.player.person.name,text});input.value='';document.querySelector('#fsMeetingChat').innerHTML=state.meeting.messages.map(msgHTML).join('');document.querySelector('#fsMeetingChat').scrollTop=99999}
  function resolveMeeting(){const m=state.meeting;if(!m.selected)return;const living=state.actors.filter(a=>a.alive);m.votes[state.player.id]=m.selected;for(const a of living){if(!a.bot)continue;let choice='skip';const witnessed=[...a.witnessed].map(id=>state.actors.find(x=>x.id===id)).filter(x=>x?.alive);if(witnessed.length)choice=pick(witnessed).id;else if(a.role==='saboteur'){const crew=living.filter(x=>x.role!=='saboteur');if(crew.length&&Math.random()<.75)choice=pick(crew).id}else{const candidates=living.filter(x=>x.id!==a.id);if(candidates.length&&Math.random()<(a.difficulty==='hard'?.72:a.difficulty==='easy'?.35:.52))choice=pick(candidates).id}m.votes[a.id]=choice}
    const count=Object.create(null);for(const v of Object.values(m.votes))count[v]=(count[v]||0)+1;const ranked=Object.entries(count).sort((a,b)=>b[1]-a[1]);let ejected=null;if(ranked[0]&&ranked[0][0]!=='skip'&&(!ranked[1]||ranked[0][1]>ranked[1][1]))ejected=state.actors.find(a=>a.id===ranked[0][0]);if(ejected){ejected.alive=false;ejected.ghost=true}const result=ejected?`${ejected.person.name} was voted out${state.confirmRoles?` · ${ROLES[ejected.role].team==='saboteur'?'SABOTEUR':'FAMILY CREW'}`:''}.`:'No one was voted out.';state.meeting.messages.push({name:'Game Lodge',text:result,system:true});const meeting=document.querySelector('.fs-meeting');meeting.innerHTML=`<div class="fs-meeting-title"><span>VOTE COMPLETE</span><h2>${result}</h2><p class="subtext">${formatVotes(count)}</p><button id="fsMeetingContinue" class="btn success">RETURN TO THE PROPERTY</button></div>`;meeting.querySelector('#fsMeetingContinue').onclick=()=>{document.querySelector('#fsMeeting')?.remove();state.meeting=null;state.phase='playing';state.running=true;last=performance.now();checkWins();if(!state.winner)raf=requestAnimationFrame(loop)}}
  function formatVotes(c){return Object.entries(c).map(([id,n])=>`${id==='skip'?'Skip':state.actors.find(a=>a.id===id)?.person.name||id}: ${n}`).join(' · ')}

  function toggleChat(){root.querySelector('#fsDrawer')?.classList.toggle('hidden');renderChat()}
  function sendChat(){const i=root.querySelector('#fsChatInput'),t=i?.value.trim();if(!t)return;addChat(state.player,t);i.value='';renderChat()}
  function addChat(a,text,system=false){state.chat.push({name:system?'Game Lodge':a?.person?.name||'Game Lodge',text,system});if(state.chat.length>50)state.chat.shift();renderChat()}
  function renderChat(){const l=root?.querySelector('#fsChatLog');if(l){l.innerHTML=state.chat.map(msgHTML).join('');l.scrollTop=99999}}
  function msgHTML(m){return `<div class="fs-chat-msg"><b>${m.name}</b> ${m.text}</div>`}

  function zoneAt(x,z){for(const q of state.map.zones||[])if(x>=q.x&&x<=q.x+q.w&&z>=q.z&&z<=q.z+q.d)return q;return null}
  function updateHud(){if(!state||!root)return;const p=state.player,role=ROLES[p.role],crewAlive=state.actors.filter(a=>a.alive&&a.role!=='saboteur').length,sabAlive=state.actors.filter(a=>a.alive&&a.role==='saboteur').length,zone=zoneAt(p.x,p.z),taskPct=state.teamTaskTotal?state.teamTaskDone/state.teamTaskTotal*100:0;root.querySelector('#fsClock').textContent=fmt(now()-state.started);root.querySelector('#fsCrewCount').textContent=`Crew ${crewAlive}`;root.querySelector('#fsSabCount').textContent=p.role==='saboteur'?`Saboteurs ${sabAlive}`:'Saboteurs ?';root.querySelector('#fsArea').textContent=`AREA · ${zone?.name||'OPEN GROUND'}`;root.querySelector('#fsTaskBar').style.width=`${taskPct}%`;const todo=p.role==='saboteur'?`Fake chores, protect your cover, or trigger a sabotage.`:`${p.tasks.filter(t=>!t.done).length} chores left · Team progress ${Math.round(taskPct)}%`;root.querySelector('#fsObjectiveText').textContent=todo;const task=nearestTask(p),body=nearestBody(p),target=p.role==='saboteur'?nearestKillTarget(p):null,vent=nearestVent(p),station=emergencyStation(),nearEmergency=dist(p,station)<120;let nearby='';if(body)nearby=`REPORT ${body.person.name}`;else if(target&&p.killCooldown<=0)nearby=`ELIMINATE ${target.person.name}`;else if(task)nearby=p.role==='saboteur'?`Fake chore · ${task.name}`:`Chore · ${task.name}`;else if(vent&&(p.role==='saboteur'||p.role==='fixer'))nearby=`Service vent · ${vent.zone}`;else if(nearEmergency)nearby='Emergency Button ready';root.querySelector('#fsNearby').textContent=nearby||'Move around the property and watch who goes where.';const primary=root.querySelector('#fsPrimary');primary.textContent=p.role==='saboteur'?(target&&p.killCooldown<=0?'ELIMINATE':task?'FAKE TASK':`COOLDOWN ${Math.ceil(p.killCooldown)}`):(state.sabotage?.critical&&dist(p,state.taskStations[0])<90?'REPAIR':task?'DO TASK':'USE');primary.disabled=(!p.alive&&!(p.ghost&&p.role!=='saboteur'))||(!task&&!target&&!(state.sabotage?.critical&&dist(p,state.taskStations[0])<90));root.querySelector('#fsSecondary').disabled=!body||!p.alive;root.querySelector('#fsEmergency').disabled=!nearEmergency||p.meetingLeft<=0||!p.alive;const special=root.querySelector('#fsSpecial');if(p.role==='saboteur'){special.textContent=state.sabotage?state.sabotage.name:state.sabotageCooldown>0?`SAB ${Math.ceil(state.sabotageCooldown)}`:'SABOTAGE';special.disabled=!!state.sabotage||state.sabotageCooldown>0}else if(p.role==='fixer'){special.textContent=p.ventCooldown>0?`VENT ${Math.ceil(p.ventCooldown)}`:'VENT';special.disabled=!vent||p.ventCooldown>0}else{special.textContent='TASK MAP';special.disabled=false}const alert=root.querySelector('#fsSabAlert');if(state.sabotage){alert.classList.remove('hidden');alert.textContent=`${state.sabotage.name} · ${Math.ceil(state.sabotage.left)}s${state.sabotage.critical?` · REPAIR IN ${state.taskStations[0].zone}`:''}`}else alert.classList.add('hidden')}
  function fmt(s){s=Math.max(0,Math.floor(s));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
  function toast(t){window.APP?.toast?.(t)}

  function checkWins(){if(state.winner)return;const crew=state.actors.filter(a=>a.alive&&a.role!=='saboteur').length,sab=state.actors.filter(a=>a.alive&&a.role==='saboteur').length;if(sab===0)return endGame('crew','Every Saboteur was voted out.');if(sab>0&&sab>=crew)return endGame('saboteur','Saboteurs reached parity with the remaining Family Crew.');if(state.teamTaskTotal>0&&state.teamTaskDone>=state.teamTaskTotal)return endGame('crew','The Family Crew completed every chore.')}
