    for(const prop of state.map.props||[]){if(Math.hypot(prop.x-p.x,prop.z-p.z)>viewRadius*1.35)continue;drawPropIcon(prop,sx(prop.x),sy(prop.z),scale)}
    for(const t of state.taskStations){if(Math.hypot(t.x-p.x,t.z-p.z)>viewRadius*1.25)continue;drawTask(t,sx(t.x),sy(t.z))}
