  function drawGround(c,W,H,p,scale){c.fillStyle='#30261d';c.fillRect(0,0,W,H);c.strokeStyle='#6d523624';c.lineWidth=1;for(let y=-30;y<H+30;y+=26){c.beginPath();c.moveTo(0,y+(p.z*.14)%26);c.lineTo(W,y+(p.z*.14)%26);c.stroke()}for(let x=-30;x<W+30;x+=54){c.beginPath();c.moveTo(x-(p.x*.18)%54,0);c.lineTo(x-(p.x*.18)%54,H);c.stroke()}}
  function drawPropIcon(prop,x,y,scale){const im=propImage(prop.type),s=clamp(42*scale,26,52);if(im&&im.complete&&im.naturalWidth){const ratio=im.naturalWidth/im.naturalHeight,w=s*ratio;ctx.drawImage(im,x-w/2,y-s*.82,w,s);return}const n=String(prop.type||'').toLowerCase();let e='📦';if(n.includes('bucket'))e='🪣';else if(n.includes('mug'))e='☕';else if(n.includes('lantern'))e='🏮';else if(n.includes('tool'))e='🧰';else if(n.includes('hay'))e='🟨';else if(n.includes('wheel'))e='🛒';else if(n.includes('gas')||n.includes('oil'))e='⛽';else if(n.includes('chair'))e='🪑';else if(n.includes('rock'))e='🪨';else if(n.includes('shovel'))e='🪏';else if(n.includes('feed'))e='🧺';ctx.font=`${clamp(18*scale,12,22)}px serif`;ctx.textAlign='center';ctx.fillText(e,x,y)}
  function drawTask(t,x,y){ctx.save();ctx.translate(x,y);ctx.fillStyle='#86b675';ctx.strokeStyle='#d9efbc';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,9,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#fff';ctx.font='900 9px system-ui';ctx.fillText('!',0,3);ctx.restore()}
  function drawVent(v,x,y,visible){ctx.save();ctx.translate(x,y);ctx.globalAlpha=visible?1:.28;ctx.fillStyle='#2b2e2f';ctx.strokeStyle=visible?'#7fc0dc':'#6e6e6e';ctx.lineWidth=2;ctx.fillRect(-13,-8,26,16);ctx.strokeRect(-13,-8,26,16);for(let i=-8;i<=8;i+=4){ctx.beginPath();ctx.moveTo(i,-6);ctx.lineTo(i,6);ctx.stroke()}ctx.restore()}
