  function drawActor(a,x,y,scale,isPlayer){if(a.ghost&&a.id!==state.player.id)return;const im=charImg(a.person,a.style),h=a.person.dog?58:82,w=h*((im.naturalWidth&&im.naturalHeight)?im.naturalWidth/im.naturalHeight:(a.person.dog?.85:.52));ctx.save();ctx.globalAlpha=a.alive?1:.45;ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(x,y+4,w*.36,5,0,Math.PI*2);ctx.fill();if(isPlayer){ctx.shadowColor='#ffe28a';ctx.shadowBlur=16}if(im.complete&&im.naturalWidth)ctx.drawImage(im,x-w/2,y-h,w,h);else{ctx.fillStyle='#8a6a4d';ctx.fillRect(x-w/3,y-h*.75,w*.66,h*.7)}ctx.shadowBlur=0;ctx.strokeStyle=isPlayer?'#ffe39b':'#16100b';ctx.lineWidth=3;ctx.fillStyle='#fff0d4';ctx.font='900 10px system-ui';ctx.textAlign='center';ctx.strokeText(a.person.name,x,y-h-6);ctx.fillText(a.person.name,x,y-h-6);if(state.player.role==='saboteur'&&a.role==='saboteur'){ctx.fillStyle='#d84f48';ctx.beginPath();ctx.arc(x+w*.37,y-h*.78,5,0,Math.PI*2);ctx.fill()}ctx.restore()}
  function drawMini(){if(!mctx||state.radioJammed)return;const W=mini._w||110,H=mini._h||84,map=state.map,p=state.player,sx=(W-8)/map.w,sz=(H-12)/map.d;mctx.clearRect(0,0,W,H);mctx.fillStyle='#11100ecc';mctx.fillRect(0,0,W,H);for(const z of map.zones||[]){mctx.fillStyle='#6d624755';mctx.fillRect(4+z.x*sx,4+z.z*sz,z.w*sx,z.d*sz)}mctx.fillStyle='#65c8f0';mctx.beginPath();mctx.arc(4+p.x*sx,4+p.z*sz,3.5,0,Math.PI*2);mctx.fill();if(p.role==='saboteur')for(const a of state.actors.filter(x=>x.alive&&x.role==='saboteur'&&x.id!==p.id)){mctx.fillStyle='#d65b55';mctx.beginPath();mctx.arc(4+a.x*sx,4+a.z*sz,2.5,0,Math.PI*2);mctx.fill()}}
  function shade(hex,amt){const m=/^#([0-9a-f]{6})$/i.exec(hex);if(!m)return hex;let n=parseInt(m[1],16),r=n>>16,g=n>>8&255,b=n&255;const f=amt>=0?255:0,p=Math.abs(amt);r=Math.round(r+(f-r)*p);g=Math.round(g+(f-g)*p);b=Math.round(b+(f-b)*p);return`rgb(${r},${g},${b})`}

